import { test, expect } from '@playwright/test';
import { loginAndGoToProducts } from './helpers/auth';

// Phase 1: Browsing — product catalog and product details

test.describe('Products — Phase 1: Browsing', () => {

  test('home page loads with title and navigation', async ({ page }) => {
    await page.goto('/');
    await expect(page).toHaveTitle(/ecommerce|shop/i);
    await expect(page.locator('body')).toBeVisible();
  });

  test('products page shows the catalog grid', async ({ page }) => {
    await page.goto('/products');
    await page.waitForSelector('h3', { state: 'visible', timeout: 20000 });
    const productCards = page.locator('h3');
    await expect(productCards.first()).toBeVisible();
    expect(await productCards.count()).toBeGreaterThan(0);
  });

  test('product card shows name and price', async ({ page }) => {
    await page.goto('/products');
    await page.waitForSelector('h3', { state: 'visible', timeout: 20000 });
    const prices = page.locator('span.text-xl.font-black.text-slate-900');
    await expect(prices.first()).toBeVisible();
    await expect(prices.first()).toContainText('$');
  });

  test('clicking a product card opens the product detail page', async ({ page }) => {
    await page.goto('/products');
    await page.waitForSelector('h3', { state: 'visible', timeout: 20000 });
    const firstProduct = page.locator('h3').first();
    const productName = await firstProduct.innerText();
    await firstProduct.click();
    await page.waitForURL(/\/product\/.+/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText(productName.trim());
  });

