    @Transactional
    public OrderResponse placeOrder(String userId, String userEmail, String idempotencyKey) {
        // Idempotency check: return existing order if this key was already processed
        var existing = orderRepository.findByIdempotencyKey(idempotencyKey);
        if (existing.isPresent()) {
            Order existingOrder = existing.get();
            String ref = buildOrderReference(existingOrder);
            log.info("Duplicate checkout request detected for idempotency key: {}", idempotencyKey);
            return new OrderResponse(existingOrder.getId(), ref, userEmail);
        }

        // 1. Retrieve cart items from Cart Service
        CartResponse cart = cartClient.getCartByUserId(userId);

        if (cart == null || cart.items().isEmpty()) {
            throw new BusinessException("Cart is empty for user: " + userId);
        }

        // 2. Collect all unique Product IDs from the cart
        List<String> productIds = cart.items().stream()
                .map(CartItemResponse::productId)
                .distinct()
                .toList();

        // 3. Batch: Single network call to fetch all product details
        List<ProductResponse> products = productClient.getProductsByIds(productIds);

        // 4. Create Maps for price, name and imageUrl lookup
        Map<String, BigDecimal> priceMap = products.stream()
                .collect(Collectors.toMap(ProductResponse::id, ProductResponse::price));
        Map<String, String> nameMap = products.stream()
                .collect(Collectors.toMap(ProductResponse::id, ProductResponse::name));
        Map<String, String> imageUrlMap = products.stream()
                .collect(Collectors.toMap(ProductResponse::id,
                        p -> p.imageUrl() != null ? p.imageUrl() : ""));

        // 5. Build Order and Items
        BigDecimal total = BigDecimal.ZERO;
        List<OrderItem> orderItems = new ArrayList<>();

