        for (var cartItem : cart.items()) {
            BigDecimal price = priceMap.get(cartItem.productId());
            if (price == null) throw new BusinessException("Price invalid. Product ID: " + cartItem.productId());

            total = total.add(price.multiply(BigDecimal.valueOf(cartItem.quantity())));

            OrderItem orderItem = new OrderItem();
            orderItem.setProductId(cartItem.productId());
            orderItem.setProductName(nameMap.get(cartItem.productId()));
            orderItem.setImageUrl(imageUrlMap.get(cartItem.productId()));
            orderItem.setQuantity(cartItem.quantity());
            orderItem.setPrice(price);
            orderItems.add(orderItem);
        }

        // 6. Finalize and Save
        Order order = Order.builder()
                .userId(userId)
                .total(total)
                .status(OrderStatus.PENDING)
                .orderDate(LocalDateTime.now())
                .idempotencyKey(idempotencyKey)
                .items(new ArrayList<>())
                .build();
        orderItems.forEach(order::addOrderItem);

        // 7. Save — catch concurrent duplicate to handle race conditions
        Order savedOrder;
        try {
            savedOrder = orderRepository.save(order);
        } catch (DataIntegrityViolationException e) {
            // Another concurrent request already created an order with this key; return that one
            return orderRepository.findByIdempotencyKey(idempotencyKey)
                    .map(o -> new OrderResponse(o.getId(), buildOrderReference(o), userEmail))
                    .orElseThrow(() -> e);
        }

        // 8. Trigger "Clear Cart" in Cart Service
        try {
            cartClient.clearCart(userId);
        } catch (Exception e) {
            log.warn("Failed to clear cart for user {}: {}", userId, e.getMessage());
        }

        String orderReference = buildOrderReference(savedOrder);

        // 9. Publish event to RabbitMQ for Notification Service
        orderProducer.sendOrderConfirmation(new OrderPlacedEvent(orderReference, userEmail));

