    public List<OrderSummaryResponse> getOrdersByUserId(String userId) {
        return orderRepository.findByUserIdOrderByOrderDateDesc(userId).stream()
                .map(order -> new OrderSummaryResponse(
                        order.getId(),
                        buildOrderReference(order),
                        order.getOrderDate().toString(),
                        "DELIVERED"
                ))
                .toList();
    }

    public OrderDetailResponse getOrderDetail(Long orderId, String userId) {
        Order order = orderRepository.findById(orderId)
                .orElseThrow(() -> new OrderNotFoundException(orderId));

        if (!order.getUserId().equals(userId)) {
            throw new OrderAccessDeniedException(orderId);
        }

        List<OrderItemDetailResponse> items = order.getItems().stream()
                .map(item -> new OrderItemDetailResponse(
                        item.getProductId(), item.getProductName(), item.getImageUrl(),
                        item.getPrice(), item.getQuantity()))
                .toList();

        return new OrderDetailResponse(
                order.getId(),
                buildOrderReference(order),
                order.getOrderDate().toString(),
                "DELIVERED",
                order.getTotal(),
                items
        );
    }

    private String buildOrderReference(Order order) {
        return "ORD-" + order.getOrderDate().getYear() + "-" + String.format("%07d", order.getId());
    }
}

