    @PatchMapping("/{userId}/items/{productId}")
    public Mono<ResponseEntity<Cart>> updateQuantity(@PathVariable String userId,
                                                      @PathVariable String productId,
                                                      @RequestParam int quantity) {
        return authenticatedUserId()
                .flatMap(authenticatedId -> {
                    validateOwnership(userId, authenticatedId);
                    return cartService.updateQuantity(userId, productId, quantity).map(ResponseEntity::ok);
                });
    }

    private Mono<String> authenticatedUserId() {
        return ReactiveSecurityContextHolder.getContext()
                .map(ctx -> ctx.getAuthentication().getName())
                .switchIfEmpty(Mono.error(new ResponseStatusException(
                        HttpStatus.UNAUTHORIZED, "Authentication required")));
    }

    private void validateOwnership(String userId, String authenticatedId) {
        if (!authenticatedId.equals(userId)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Access denied: cart belongs to a different user");
        }
    }
}

