@Component
public class CartClient {

    private final WebClient webClient;
    private final ReactiveCircuitBreaker circuitBreaker;

    @Value("${services.cart-service.uri}")
    private String cartServiceUri;

    @SuppressWarnings("rawtypes")
    public CartClient(WebClient.Builder builder, ReactiveCircuitBreakerFactory factory) {
        this.webClient = builder.build();
        this.circuitBreaker = factory.create("cart-service");
    }

    public Mono<CartResponse> addToCart(AddToCartInput input) {
        return jwt().flatMap(jwt ->
                webClient.post()
                        .uri(cartServiceUri + "/" + jwt.getSubject() + "/items")
                        .header("Authorization", "Bearer " + jwt.getTokenValue())
                        .bodyValue(input)
                        .retrieve()
                        .bodyToMono(CartResponse.class)
                        .transform(mono -> circuitBreaker.run(mono,
                                t -> Mono.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "cart-service unavailable")))));
    }

    public Mono<CartResponse> updateQuantity(String productId, int quantity) {
        return jwt().flatMap(jwt ->
                webClient.patch()
                        .uri(uriBuilder -> UriComponentsBuilder
                                .fromUriString(cartServiceUri)
                                .path("/{userId}/items/{productId}")
                                .queryParam("quantity", quantity)
                                .buildAndExpand(jwt.getSubject(), productId)
                                .toUri())
                        .header("Authorization", "Bearer " + jwt.getTokenValue())
                        .retrieve()
                        .bodyToMono(CartResponse.class)
                        .transform(mono -> circuitBreaker.run(mono,
                                t -> Mono.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "cart-service unavailable")))));
    }

