    Mono<Boolean> isAccountLocked(String username) {
        String attackDetectionBaseUri = usersUri.replace("/users", "/attack-detection/brute-force/users");
        return getAdminAccessToken()
                .flatMap(token ->
                        webClient.get()
                                .uri(usersUri + "?username=" + username + "&exact=true")
                                .header("Authorization", "Bearer " + token)
                                .retrieve()
                                .bodyToFlux(Map.class)
                                .next()
                                .flatMap(user -> {
                                    String userId = (String) user.get("id");
                                    return webClient.get()
                                            .uri(attackDetectionBaseUri + "/" + userId)
                                            .header("Authorization", "Bearer " + token)
                                            .retrieve()
                                            .bodyToMono(Map.class)
                                            .map(status -> Boolean.TRUE.equals(status.get("disabled")));
                                })
                                .switchIfEmpty(Mono.just(false)))
                .onErrorReturn(false);
    }

    static final String LOCKED_MESSAGE =
            "Your account has been temporarily locked due to too many failed login attempts. Please try again later.";
    static final String INVALID_CREDENTIALS_MESSAGE = "Invalid username or password.";

    static String toUserMessage(String keycloakError) {
        if (keycloakError == null || keycloakError.isBlank()) {
            return INVALID_CREDENTIALS_MESSAGE;
        }
        if (keycloakError.toLowerCase().contains("disabled")) {
            return LOCKED_MESSAGE;
        }
        return INVALID_CREDENTIALS_MESSAGE;
    }

