@Service
public class AuthService {

    private final WebClient webClient;

    @Value("${keycloak.token-uri}")
    private String tokenUri;

    @Value("${keycloak.users-uri}")
    private String usersUri;

    @Value("${keycloak.client-id}")
    private String clientId;

    @Value("${keycloak.client-secret}")
    private String clientSecret;

    public AuthService(WebClient.Builder webClientBuilder) {
        this.webClient = webClientBuilder.build();
    }

    public Mono<LoginResponse> generateToken(String username, String password) {
        return webClient.post()
                .uri(tokenUri)
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .body(BodyInserters.fromFormData("grant_type", "password")
                        .with("client_id", clientId)
                        .with("client_secret", clientSecret)
                        .with("username", username)
                        .with("password", password))
                .retrieve()
                .onStatus(
                        status -> status.is4xxClientError(),
                        response -> response.bodyToMono(Map.class)
                                .flatMap(body -> isAccountLocked(username)
                                        .flatMap(locked -> Mono.error(new ResponseStatusException(
                                                HttpStatus.UNAUTHORIZED,
                                                locked ? LOCKED_MESSAGE : INVALID_CREDENTIALS_MESSAGE)))))
                .bodyToMono(LoginResponse.class);
    }

    // Package-private so tests can spy on it

