import { Page } from '@playwright/test';

export const TEST_USER = {
  username: 'bart',
  password: 'simpson',
};

// Keycloak can be slow on cold start — use a generous timeout across all auth operations
const AUTH_TIMEOUT = 30000;

/**
 * Logs in with the given credentials via the login form and waits for redirect to /products.
 */
export async function login(page: Page, username = TEST_USER.username, password = TEST_USER.password) {
  await page.goto('/login');
  await page.waitForSelector('input#username', { state: 'visible', timeout: AUTH_TIMEOUT });
  await page.fill('input#username', username);
  await page.fill('input#password', password);
  await page.locator('button[type="submit"]').click({ noWaitAfter: true });
  // waitUntil: 'commit' — Angular SPA uses history.pushState; no browser 'load' event fires.
  // 'commit' waits only for the URL to change, which is all we need here.
  await page.waitForURL((url) => !url.pathname.includes('/login'), {
    timeout: AUTH_TIMEOUT,
    waitUntil: 'commit',
  });
}

/**
 * Logs in and navigates to the products page, waiting for at least one product card.
 */
export async function loginAndGoToProducts(page: Page) {
  await login(page);
  await page.goto('/products');
  await page.waitForSelector('h3', { state: 'visible', timeout: 20000 });
}

