    @SchemaMapping(typeName = "Cart", field = "totalPrice")
    public Mono<Double> getTotalPrice(CartResponse cart) {
        if (cart.items() == null || cart.items().isEmpty()) {
            return Mono.just(0.0);
        }

        List<String> ids = cart.items().stream()
                .map(CartItemResponse::productId)
                .toList();

        return productClient.getProductsByIds(ids)
                .collectMap(ProductResponse::id)
                .map(productsById -> cart.items().stream()
                        .mapToDouble(item -> {
                            ProductResponse p = productsById.get(item.productId());
                            return p != null ? p.price().doubleValue() * item.quantity() : 0.0;
                        })
                        .sum());
    }

}

