@Injectable({
  providedIn: 'root',
})
export class Auth {
  private http = inject(HttpClient);
  private jwtHelper = new JwtHelperService();

  // Point to API Gateway, not directly to Auth Service
  private apiUrl = `${environment.apiUrl}/auth`;

  public currentUser = signal<any>(this.decodeUserFromToken());

  // Track login status for the UI (Show Login vs Logout button)
  private isLoggedInSubject = new BehaviorSubject<boolean>(this.hasToken());
  public isLoggedIn$ = this.isLoggedInSubject.asObservable();

  login(username: string, password: string): Observable<AuthResponse> {
    return this.http.post<AuthResponse>(`${this.apiUrl}/login`, { username, password }).pipe(
      tap((response) => {
        // Save tokens to LocalStorage
        localStorage.setItem('access_token', response.access_token);
        localStorage.setItem('refresh_token', response.refresh_token);

        // Update the signal after successful login
        this.currentUser.set(this.decodeUserFromToken());

        this.isLoggedInSubject.next(true);
      })
    );
  }

  register(registerRequest: RegisterRequest): Observable<any> {
    return this.http.post<RegisterRequest>(`${this.apiUrl}/register`, registerRequest);
  }

  logout(): void {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');

    // Reset the signal on logout
    this.currentUser.set(null);

    this.isLoggedInSubject.next(false);
  }

  getToken(): string | null {
    return localStorage.getItem('access_token');
  }

  private hasToken(): boolean {
    return !!localStorage.getItem('access_token');
  }

