// Define the GraphQL Query
const GET_PRODUCTS = gql`
  query GetProducts {
    products {
      id
      name
      price
      description
      stockQuantity
      imageUrl
    }
  }
`;

const GET_PRODUCT_BY_ID = gql`
  query GetProduct($id: ID!) {
    productById(id: $id) {
      id
      name
      description
      price
      stockQuantity
      category
      imageUrl
    }
  }
`;

@Injectable({
  providedIn: 'root',
})
export class ProductService {
  private apollo = inject(Apollo);

  getAvailableProducts(): Observable<ProductResponse[]> {
    return this.apollo
      .watchQuery<{ products: ProductResponse[] }>({
        query: GET_PRODUCTS,
        fetchPolicy: 'network-only', // Ensures always get fresh data from the server
      })
      .valueChanges.pipe(map((result) => result.data?.products as ProductResponse[]));
  }

  getProductById(id: string): Observable<ProductResponse> {
    return this.apollo
      .query<{ productById: ProductResponse }>({
        query: GET_PRODUCT_BY_ID,
        variables: { id },
      })
      .pipe(map((result) => result.data?.productById as ProductResponse));
  }
}

