@Configuration
public class RabbitMQConfig {

    public static final String EXCHANGE    = "order.exchange";
    public static final String QUEUE       = "order.placed.queue";
    public static final String ROUTING_KEY = "order.placed";

    public static final String DLX             = "order.dlx";
    public static final String DLQ             = "order.placed.dlq";
    public static final String DLQ_ROUTING_KEY = "order.dlq";

    /**
     * Creates a Direct Exchange.
     * A Direct Exchange delivers messages to queues based on an exact match
     * between the routing key in the message and the routing key in the binding.
     */
    @Bean
    public DirectExchange orderExchange() {
        return new DirectExchange(EXCHANGE);
    }

    /**
     * Creates the main queue with dead-letter arguments so that messages
     * rejected after all retry attempts are forwarded to the DLX instead of
     * being silently dropped.
     */
    @Bean
    public Queue orderQueue() {
        return QueueBuilder.durable(QUEUE)
                .withArgument("x-dead-letter-exchange", DLX)
                .withArgument("x-dead-letter-routing-key", DLQ_ROUTING_KEY)
                .build();
    }

    /**
     * Binds the Queue to the Exchange using a specific Routing Key.
     * This "glues" the infrastructure together so the exchange knows
     * where to send messages marked with "order.placed".
     */
    @Bean
    public Binding binding(Queue orderQueue, DirectExchange orderExchange) {
        return BindingBuilder.bind(orderQueue)
                .to(orderExchange)
                .with(ROUTING_KEY);
    }

    /**
     * Dead-Letter Exchange that receives messages rejected by the main queue.
     * Acts as a router to the Dead-Letter Queue.
     */
    @Bean
    public DirectExchange deadLetterExchange() {
        return new DirectExchange(DLX);
    }

