import { HttpErrorResponse, HttpHandlerFn, HttpInterceptorFn, HttpRequest } from '@angular/common/http';
import { inject } from '@angular/core';
import { throwError } from 'rxjs/internal/observable/throwError';
import { catchError } from 'rxjs/internal/operators/catchError';
import { switchMap } from 'rxjs/internal/operators/switchMap';
import { Auth } from '../services/auth';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const authService = inject(Auth);
  const token = localStorage.getItem('access_token');

  // 1. Define Public Endpoints
  // We check if the URL starts with /auth/ or is a GET request to products
  const isPublicAuth =
    req.url.includes('/auth/login') ||
    req.url.includes('/auth/register') ||
    req.url.includes('/auth/refresh');
  const isPublicProducts = req.url.includes('/api/products') && req.method === 'GET';

  // 2. Attach token ONLY if user is logged in AND it's not a public route
  if (token && !isPublicAuth && !isPublicProducts) {
    req = req.clone({
      setHeaders: {
        Authorization: `Bearer ${token}`,
      },
    });
  }

  return next(req).pipe(
    catchError((error) => {
      if (shouldAttemptRefresh(error, isPublicAuth)) {
        return handleTokenRefresh(authService, req, next);
      }
      return throwError(() => error);
    })
  );
};

/**
 * Determines if we should attempt to refresh the token.
 * We only refresh if it's a 401 (Unauthorized) and the user isn't already on a login/register page.
 */
function shouldAttemptRefresh(error: unknown, isPublicAuth: boolean): boolean {
  return error instanceof HttpErrorResponse && error.status === 401 && !isPublicAuth;
}

