@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink, RouterLinkActive, CommonModule],
  templateUrl: './app.html',
  styleUrl: './app.scss',
})
export class App implements OnInit {
  authService = inject(Auth);
  private cartService = inject(CartService);
  private router = inject(Router);

  protected readonly title = signal('frontend');

  currentYear: number = new Date().getFullYear();

  itemCount = this.cartService.itemCount;

  // Reference to the profile div specifically
  @ViewChild('profileMenu') profileMenu!: ElementRef;
  isMenuOpen = false;

  private notificationService = inject(Notification);
  notification$ = this.notificationService.message$;

  constructor() {
    // This watches for every page change and closes the profile menu
    this.router.events.pipe(filter((event) => event instanceof NavigationEnd)).subscribe(() => {
      this.isMenuOpen = false;
    });
  }

  ngOnInit(): void {
    if (this.authService.currentUser()) {
      this.cartService.refreshCart().subscribe({
        next: (data) => {},
        error: (err) => console.error('Failed to initialize cart:', err),
      });
    }
  }

  toggleMenu() {
    this.isMenuOpen = !this.isMenuOpen;
  }

  logout() {
    this.authService.logout();
    this.isMenuOpen = false;
    this.router.navigate(['/login']);
  }

  // Closes the menu if a click occurs outside the navbar
  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    // If the menu is closed, do nothing
    if (!this.isMenuOpen) return;

    // Check if the click was outside the profileMenu div
    if (this.profileMenu && !this.profileMenu.nativeElement.contains(event.target)) {
      this.isMenuOpen = false;
    }
  }
}

