export class CartService {
  private apollo = inject(Apollo);

  // Create a signal to hold the state
  cartState = signal<CartResponse | null>(null);

  // Expose read-only signals for components
  public cart = this.cartState.asReadonly();

  // Expose a computed signal for the item count
  public itemCount = computed(() => {
    return this.cart()?.items.reduce((acc, item) => acc + item.quantity, 0) || 0;
  });

  addToCart(productId: string, quantity: number): Observable<CartResponse> {
    return this.apollo
      .mutate<{ addToCart: CartResponse }>({
        mutation: ADD_TO_CART_MUTATION,
        variables: {
          input: {
            productId,
            quantity,
          },
        },
      })
      .pipe(
        tap((result) => {
          if (result.data?.addToCart) {
            this.cartState.set(result.data?.addToCart);
          }
        }),
        map((result) => result.data!.addToCart)
      );
  }

  getCart(): Observable<CartResponse> {
    return this.apollo
      .watchQuery<{ cart: CartResponse }>({
        query: GET_CART_QUERY,
        fetchPolicy: 'network-only',
      })
      .valueChanges.pipe(map((result) => result.data?.cart as CartResponse));
  }

  refreshCart(): Observable<CartResponse> {
    return this.getCart().pipe(
      tap((result: CartResponse) => {
        this.cartState.set(result);
      })
    );
  }

  removeItem(productId: string) {
    this.apollo
      .mutate<{ removeItem: CartResponse }>({
        mutation: REMOVE_ITEM_MUTATION,
        variables: { productId },
      })
      .subscribe((result) => {
        if (result.data?.removeItem) {
          this.cartState.set(result.data?.removeItem);
        }
      });
  }

  updateQuantity(productId: string, quantity: number) {
    this.apollo
      .mutate<{ updateQuantity: CartResponse }>({
        mutation: UPDATE_QUANTITY_MUTATION,
        variables: { productId, quantity },
      })
      .subscribe((result) => {
        if (result.data?.updateQuantity) {
          this.cartState.set(result.data?.updateQuantity);
        }
      });
  }
}

