@Service
@Slf4j
public class ProductService {

    private final ProductRepository productRepository;

    public ProductService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    public void createProduct(ProductRequest productRequest) {
        Product product = ProductMapper.INSTANCE.mapProductRequestToProduct(productRequest);
        this.productRepository.save(product);
        log.info("Product {} is saved", product.getId());
    }

    public void updateProduct(String id, ProductRequest productRequest) {
        Product product = this.productRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Product not found"));
        product.setName(productRequest.name());
        product.setDescription(productRequest.description());
        product.setPrice(productRequest.price());
        product.setStockQuantity(productRequest.stockQuantity());
        product.setSkuCode(productRequest.skuCode());
        product.setCategory(productRequest.category());
        this.productRepository.save(product);
        log.info("Product {} is updated", product.getId());
    }

    public ProductResponse getProductById(String id) {
        Product product = this.productRepository.findById(id)
                .orElseThrow(() -> new ProductNotFoundException(id));
        return ProductMapper.INSTANCE.mapProductToProductResponse(product);
    }

    public List<ProductResponse> getAllProducts() {
        return this.productRepository.findAll()
                .stream()
                .map(ProductMapper.INSTANCE::mapProductToProductResponse)
                .toList();
    }

    public void deleteProduct(String id) {
        this.productRepository.deleteById(id);
        log.info("Product {} is deleted", id);
    }

