package com.ecommerce.notification_service.config;

import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.context.propagation.ContextPropagators;
import io.opentelemetry.sdk.OpenTelemetrySdk;
import io.opentelemetry.sdk.resources.Resource;

import io.opentelemetry.api.common.Attributes;
import io.opentelemetry.api.common.AttributeKey;
import org.springframework.core.env.Environment;
import io.opentelemetry.sdk.trace.SdkTracerProvider;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration(proxyBeanMethods = false)
public class OpenTelemetryConfig {

    @Bean
    @ConditionalOnMissingBean
    Resource otelResource(Environment environment) {
        String serviceName = environment.getProperty("spring.application.name", "unknown-service");
        return Resource.getDefault().merge(
                Resource.create(Attributes.of(AttributeKey.stringKey("service.name"), serviceName))
        );
    }

    @Bean
    @ConditionalOnMissingBean
    OpenTelemetry openTelemetry(ObjectProvider<SdkTracerProvider> tracerProvider,
                                ObjectProvider<ContextPropagators> propagators) {
        SdkTracerProvider sdkTracerProvider = tracerProvider.getIfAvailable();
        if (sdkTracerProvider == null) {
            return OpenTelemetry.noop();
        }
        return OpenTelemetrySdk.builder()
                .setTracerProvider(sdkTracerProvider)
                .setPropagators(propagators.getIfAvailable(ContextPropagators::noop))
                .buildAndRegisterGlobal();
    }
}
